<?php
require_once 'config.php';
$auth = $_SESSION['auth'] ?? null;
if (!$auth) { header('Location: login.php'); exit; }

$company = [];
try { foreach ($pdo->query("SELECT setting_key,setting_value FROM company_settings") as $r) $company[$r['setting_key']]=$r['setting_value']; } catch(Exception $ignore){}
$company += ['company_name'=>'OKOYA FOOD COMPANY LIMITED','company_dept'=>'Staff Management & HR Department','company_address'=>'KM 7 Idi APA Community, Shaki, Oyo State, Nigeria','company_tagline'=>'POVERTY ERADICATION • REDUCE INEQUALITY • LEAVE NO ONE BEHIND'];

function e(?string $s):string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function fmtN($n):string{return '₦'.number_format((float)$n,2);}
function flash(string $type,string $msg):void{$_SESSION['flash']=['type'=>$type,'msg'=>$msg];}
function get_flash():?array{$f=$_SESSION['flash']??null;unset($_SESSION['flash']);return $f;}

if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='delete_order') {
    $id=(int)($_POST['order_id']??0);
    if($id>0){
        try{
            $pdo->prepare("DELETE FROM order_signatures WHERE order_id=?")->execute([$id]);
            $pdo->prepare("DELETE FROM payments WHERE order_id=?")->execute([$id]);
            $pdo->prepare("DELETE FROM order_status_history WHERE order_id=?")->execute([$id]);
            $pdo->prepare("DELETE FROM orders WHERE id=?")->execute([$id]);
            flash('success','Order deleted successfully.');
        }catch(Exception $e){flash('error','Delete failed: '.$e->getMessage());}
    }
    header('Location: order_register.php');exit;
}

if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='update_order_full') {
    $id=(int)($_POST['order_id']??0);
    if($id>0){
        try{
            $kg=floatval($_POST['kilograms']??0);$up=floatval($_POST['unit_price']??0);$tot=$kg*$up;
            $truckPrice=floatval($_POST['truck_price']??0);$newStatus=$_POST['status']??'Pending';$isPaid=isset($_POST['is_paid'])?1:0;
            $pdo->prepare("UPDATE orders SET order_type=?,order_date=?,description=?,kilograms=?,unit_price=?,total_amount=?,truck_price=?,departure_location=?,destination_location=?,status=?,is_paid=? WHERE id=?")
                ->execute([$_POST['order_type']??'outbound',$_POST['order_date']??date('Y-m-d'),trim($_POST['description']??''),$kg,$up,$tot,$truckPrice?:null,trim($_POST['departure_location']??'')?:null,trim($_POST['destination_location']??'')?:null,$newStatus,$isPaid,$id]);
            if($isPaid){$pdo->prepare("UPDATE payments SET status='Paid',paid_at=NOW() WHERE order_id=?")->execute([$id]);}
            else{$pdo->prepare("UPDATE payments SET status='Unpaid',paid_at=NULL WHERE order_id=?")->execute([$id]);}
            $bank=trim($_POST['bank']??'');$accNo=trim($_POST['account_no']??'');$accName=trim($_POST['account_name']??'');
            if($bank||$accNo||$accName){
                $clientId=null;try{$st=$pdo->prepare("SELECT client_id FROM orders WHERE id=?");$st->execute([$id]);$row=$st->fetch();if($row)$clientId=(int)$row['client_id'];}catch(Exception $ignore){}
                if($clientId){$pdo->prepare("UPDATE clients SET bank_name=COALESCE(NULLIF(?,''),bank_name),bank_account_no=COALESCE(NULLIF(?,''),bank_account_no),bank_account_name=COALESCE(NULLIF(?,''),bank_account_name) WHERE id=?")->execute([$bank,$accNo,$accName,$clientId]);}
            }
            try{$pdo->prepare("INSERT INTO order_status_history (order_id,new_status,changed_by,note) VALUES(?,?,?,?)")->execute([$id,$newStatus,$auth['id'],'Full edit via Order Register']);}catch(Exception $ignore){}
            flash('success','Order updated successfully.');
        }catch(Exception $e){flash('error','Update failed: '.$e->getMessage());}
    }
    header('Location: order_register.php');exit;
}

$search=trim($_GET['search']??'');$filterStatus=$_GET['status']??'';$filterDate=$_GET['date']??'';
$hasFilter=($search!==''||$filterStatus!==''||$filterDate!=='');
$where=[];$params=[];
if($search!==''){$where[]="(o.order_no LIKE ? OR c.name LIKE ? OR c.phone LIKE ? OR o.departure_location LIKE ? OR o.destination_location LIKE ?)";$params[]="%$search%";$params[]="%$search%";$params[]="%$search%";$params[]="%$search%";$params[]="%$search%";}
if($filterStatus!==''){$where[]="o.status=?";$params[]=$filterStatus;}
if($filterDate!==''){$where[]="o.order_date=?";$params[]=$filterDate;}
$whereClause=$where?'WHERE '.implode(' AND ',$where):'';
$limitClause=$hasFilter?'':'LIMIT 10';

try{
    $sql="SELECT o.id,o.order_no,o.order_type,o.order_date,o.description,o.kilograms,o.unit_price,o.total_amount,o.truck_price,o.departure_location,o.destination_location,o.status,o.is_paid,o.driver_id,o.created_at,c.name AS client_name,c.phone AS client_phone,c.email AS client_email,p.name AS product_name,p.code AS product_code,p.image_url AS product_img,pay.bank_name,pay.account_no,pay.account_name,d.full_name AS driver_name,d.vehicle_plate AS driver_plate FROM orders o JOIN clients c ON c.id=o.client_id JOIN products p ON p.id=o.product_id LEFT JOIN payments pay ON pay.order_id=o.id LEFT JOIN drivers d ON d.id=o.driver_id $whereClause ORDER BY o.created_at DESC $limitClause";
    $st=$pdo->prepare($sql);$st->execute($params);$orders=$st->fetchAll(PDO::FETCH_ASSOC);
}catch(Exception $e){$orders=[];}

try{
    $totalOrders=(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn();
    $totalRevenue=(float)$pdo->query("SELECT IFNULL(SUM(amount),0) FROM payments WHERE status='Paid'")->fetchColumn();
    $pendingCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Pending'")->fetchColumn();
    $deliveredCnt=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Delivered'")->fetchColumn();
}catch(Exception $e){$totalOrders=$totalRevenue=$pendingCount=$deliveredCnt=0;}

$flashData=get_flash();
?>
