<script>
var $=function(id){return document.getElementById(id)};
var esc=function(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c})};
var fmt=function(n){return '\u20A6'+Number(n||0).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})};
var CO={name:<?php echo json_encode($company['company_name']); ?>,addr:<?php echo json_encode($company['company_address']); ?>,dept:<?php echo json_encode($company['company_dept']); ?>,tag:<?php echo json_encode($company['company_tagline']); ?>};

function toast(msg,type){var t=document.createElement('div');t.className='toast '+(type==='error'?'error':(type==='info'?'info':''));t.innerHTML='<span>'+(type==='error'?'\u26A0\uFE0F':'\u2705')+'</span>'+esc(msg);$('toastWrap').appendChild(t);setTimeout(function(){t.classList.add('out')},3000);setTimeout(function(){t.remove()},3500);}
var store={get:function(k,d){try{var v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}},set:function(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};
var sunSVG='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2.5M12 19.5V22M2 12h2.5M19.5 12H22M4.6 4.6l1.8 1.8M17.6 17.6l1.8 1.8M4.6 19.4l1.8-1.8M17.6 6.4l1.8-1.8"/></svg>';
var moonSVG='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8Z"/></svg>';
function setTheme(t){document.documentElement.dataset.theme=t;store.set('okoya_theme',t);$('themeBtn').innerHTML=t==='dark'?sunSVG:moonSVG;}
$('themeBtn').addEventListener('click',function(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')});
setTheme(store.get('okoya_theme','light'));

function closeModal(id){$(id).classList.remove('open')}
document.querySelectorAll('.modal-overlay').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)m.classList.remove('open')})});
document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.modal-overlay.open').forEach(function(m){m.classList.remove('open')})});

function updateBulkBar(){var checked=document.querySelectorAll('.order-chk:checked');$('bulkCount').textContent=checked.length;$('bulkBar').classList.toggle('visible',checked.length>0);document.querySelectorAll('tr[data-id]').forEach(function(tr){var chk=tr.querySelector('.order-chk');tr.classList.toggle('selected',chk&&chk.checked)});}
$('selectAll').addEventListener('change',function(){document.querySelectorAll('.order-chk').forEach(function(c){c.checked=this.checked});updateBulkBar()});
document.querySelectorAll('.order-chk').forEach(function(c){c.addEventListener('change',updateBulkBar)});
$('btnClearSel').addEventListener('click',function(){document.querySelectorAll('.order-chk').forEach(function(c){c.checked=false});$('selectAll').checked=false;updateBulkBar()});

function getSelectedData(){var selected=[];document.querySelectorAll('tr[data-id]').forEach(function(tr){var chk=tr.querySelector('.order-chk');if(chk&&chk.checked){try{selected.push(JSON.parse(tr.dataset.bank))}catch(e){}}});return selected;}

$('btnExportCsv').addEventListener('click',function(){
  var selected=getSelectedData();if(!selected.length){toast('No orders selected','error');return;}
  var csv='\ufeffReciever Name,Reciever Account No,Amount,Sender Narration,Receiever\'s Narration,BankCode\n';
  selected.forEach(function(s){var n='Salary Payment - '+new Date().toLocaleDateString('en-NG',{month:'long',year:'numeric'});csv+=['"'+String(s.client||'').replace(/"/g,'""')+'"','"'+String(s.acc_no||'').replace(/"/g,'""')+'"','"'+Number(s.amount||0).toFixed(2)+'"','"'+n.replace(/"/g,'""')+'"','"'+String(s.client||'').replace(/"/g,'""')+'"','""'].join(',')+'\n';});
  var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='Bulk-Payment-Upload-'+new Date().toISOString().slice(0,10)+'.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);toast('CSV exported ('+selected.length+')','success');
});

$('btnExportXls').addEventListener('click',function(){
  var selected=getSelectedData();if(!selected.length){toast('No orders selected','error');return;}
  var h='<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"><style>body{font-family:Calibri,sans-serif;font-size:11pt}table{border-collapse:collapse;width:100%}th{background:#059669;color:#fff;font-size:9pt;font-weight:bold;padding:6pt 8pt;text-align:left;border:1pt solid #047857}td{padding:5pt 8pt;border:1pt solid #ddd;font-size:10pt}.money{mso-number-format:"\\#\\,\\#\\#0\\.00";text-align:right}</style></head><body><table><tr><th>Receiver Full Name</th><th>Account no/Mobile no/Card no</th><th>Card Client Id</th><th>Wallet Provider</th><th>Amount in NGN</th><th>Bank Name/Institution Name</th></tr>';
  selected.forEach(function(s){h+='<tr><td>'+esc(s.client||'')+'</td><td style="mso-number-format:\\@">'+esc(s.acc_no||'')+'</td><td></td><td></td><td class="money">'+Number(s.amount||0).toFixed(2)+'</td><td>'+esc(s.bank||'')+'</td></tr>';});
  h+='</table></body></html>';
  var blob=new Blob(['\ufeff'+h],{type:'application/vnd.ms-excel'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='Salary-Disbursement-'+new Date().toISOString().slice(0,10)+'.xls';document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);toast('Excel exported ('+selected.length+')','success');
});

