  var h='<div class="vm-section"><div class="vm-section-title"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg> Order Information</div><div class="vm-grid">'+field('Order Number',d.order_no,true,false)+field('Order Type',(d.order_type||'outbound').toUpperCase(),false,false)+field('Order Date',d.date,false,false)+field('Status',d.status,false,false)+field('Payment',d.is_paid==1?'Paid':'Unpaid',false,false)+field('Created',d.created_at||d.date,false,false)+field('Description',d.description,false,true)+'</div></div>';
  h+='<div class="vm-section"><div class="vm-section-title"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg> Client</div><div class="vm-grid">'+field('Client Name',d.client,false,true)+field('Phone',d.phone,false,false)+field('Email',d.email,false,false)+'</div></div>';
  h+='<div class="vm-section"><div class="vm-section-title"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg> Product</div><div class="vm-grid">'+field('Product',d.product,false,true)+field('Quantity',d.kg>0?Number(d.kg).toLocaleString()+' kg':null,false,false)+field('Unit Price',d.unit_price>0?fmt(d.unit_price):null,true,false)+'</div></div>';
  h+='<div style="background:linear-gradient(135deg,var(--green),var(--green2));border-radius:10px;padding:12px 16px;color:#fff;display:flex;justify-content:space-between;align-items:center;margin:14px 0"><span style="font-size:8px;font-weight:800;letter-spacing:1px;text-transform:uppercase;opacity:.85">Total Amount</span><span style="font-family:var(--fm);font-size:18px;font-weight:700">'+fmt(d.amount)+'</span></div>';
  h+='<div class="vm-section"><div class="vm-section-title"><svg class="icon-svg" viewBox="0 0 24 24"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg> Logistics</div><div class="vm-grid">'+field('Driver',d.driver,false,false)+field('Vehicle Plate',d.driver_plate,false,false)+field('Truck Price',d.truck_price>0?fmt(d.truck_price):null,true,false)+field('Departure',d.departure,false,false)+field('Destination',d.destination,false,false)+'</div></div>';
  h+='<div class="vm-section"><div class="vm-section-title"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M3 21h18M3 10h18M5 6l7-3 7 3M4 10v11M20 10v11M8 14v3M12 14v3M16 14v3"/></svg> Bank Details</div><div class="vm-grid">'+field('Bank Name',d.bank,false,true)+field('Account Number',d.acc_no,true,false)+field('Account Name',d.acc_name,false,true)+'</div></div>';
  $('vmTitle').textContent=d.order_no||'Order Details';$('vmBody').innerHTML=h;$('viewModal').classList.add('open');
})});

