/* PRINT TICKET - Only prints dedicated document */
function printTicket(d){
  var now=new Date().toLocaleString('en-NG',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
  var netKg=Number(d.kg||0);
  var h='<div style="font-family:Arial,Helvetica,sans-serif;color:#1a231d;font-size:9pt">'+
  '<div style="display:flex;align-items:center;gap:12pt;border-bottom:3pt double #059669;padding-bottom:10pt;margin-bottom:12pt">'+
    '<img class="pt-logo" src="logo.ico" alt="Logo">'+
    '<div style="flex:1"><div style="font-size:14pt;font-weight:800;color:#059669;line-height:1.15">'+esc(CO.name)+'</div><div style="font-size:6.5pt;color:#5a655c;margin-top:2pt">'+esc(CO.addr)+'</div><div style="font-size:6pt;color:#5a655c;margin-top:1pt">'+esc(CO.dept)+'</div><div style="font-size:4.5pt;font-weight:800;letter-spacing:1.2pt;color:#b57e17;margin-top:2pt;text-transform:uppercase">'+esc(CO.tag)+'</div></div>'+
    '<div style="text-align:right;flex:none"><div style="background:#059669;color:#fff;font-size:8pt;font-weight:800;letter-spacing:1pt;padding:4pt 10pt;border-radius:3pt;display:inline-block;margin-bottom:3pt">ORDER TICKET</div><div style="font-family:monospace;font-size:11pt;font-weight:700;color:#059669;margin-top:2pt">'+esc(d.order_no)+'</div><div style="font-size:5.5pt;color:#667268;margin-top:2pt">Date: '+esc(d.date)+'</div><div style="font-size:5.5pt;color:#667268;margin-top:1pt">Printed: '+now+'</div></div>'+
  '</div>'+
  '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8pt;margin-bottom:8pt">'+
    '<div style="border:1pt solid #dfe5dd;border-radius:4pt;overflow:hidden"><div style="background:#f1f5f9;font-size:5.5pt;font-weight:800;letter-spacing:.8pt;text-transform:uppercase;padding:3pt 7pt;border-bottom:1pt solid #dfe5dd;color:#64748b">Client Information</div><div style="padding:6pt 7pt"><div style="font-weight:700;font-size:9.5pt">'+esc(d.client||'Walk-in Client')+'</div><div style="font-size:6.5pt;color:#64748b;margin-top:2pt">'+esc(d.phone||'—')+'</div><div style="font-size:6.5pt;color:#64748b;margin-top:1pt">'+esc(d.email||'—')+'</div></div></div>'+
    '<div style="border:1pt solid #dfe5dd;border-radius:4pt;overflow:hidden"><div style="background:#f1f5f9;font-size:5.5pt;font-weight:800;letter-spacing:.8pt;text-transform:uppercase;padding:3pt 7pt;border-bottom:1pt solid #dfe5dd;color:#64748b">Product Details</div><div style="padding:6pt 7pt"><div style="font-weight:700;font-size:9.5pt">'+esc(d.product||'—')+'</div><div style="font-size:6.5pt;color:#64748b;margin-top:2pt">'+netKg.toLocaleString()+' kg @ '+fmt(d.unit_price||0)+'/kg</div>'+(d.description?'<div style="font-size:6pt;color:#64748b;margin-top:2pt;font-style:italic">'+esc(d.description)+'</div>':'')+'</div></div>'+
  '</div>'+
  '<div style="background:#059669;color:#fff;border-radius:6pt;padding:10pt 14pt;display:flex;justify-content:space-between;align-items:center;margin-bottom:8pt"><span style="font-size:6pt;font-weight:800;letter-spacing:1pt;text-transform:uppercase;opacity:.85">Total Amount</span><span style="font-family:monospace;font-size:18pt;font-weight:700">'+fmt(d.amount||0)+'</span></div>'+
  '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8pt;margin-bottom:8pt">'+
    '<div style="border:1pt solid #dfe5dd;border-radius:4pt;overflow:hidden"><div style="background:#f1f5f9;font-size:5.5pt;font-weight:800;letter-spacing:.8pt;text-transform:uppercase;padding:3pt 7pt;border-bottom:1pt solid #dfe5dd;color:#64748b">Logistics &amp; Route</div><div style="padding:6pt 7pt"><div style="font-size:6.5pt;margin-bottom:2pt"><b>Driver:</b> '+esc(d.driver||'Not assigned')+(d.driver_plate?' ('+esc(d.driver_plate)+')':'')+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>Truck Cost:</b> '+(d.truck_price>0?fmt(d.truck_price):'—')+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>Type:</b> '+esc((d.order_type||'outbound').toUpperCase())+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>From:</b> '+esc(d.departure||'—')+'</div><div style="font-size:6.5pt"><b>To:</b> '+esc(d.destination||'—')+'</div></div></div>'+
    '<div style="border:1pt solid #dfe5dd;border-radius:4pt;overflow:hidden"><div style="background:#f1f5f9;font-size:5.5pt;font-weight:800;letter-spacing:.8pt;text-transform:uppercase;padding:3pt 7pt;border-bottom:1pt solid #dfe5dd;color:#64748b">Payment &amp; Bank</div><div style="padding:6pt 7pt"><div style="font-size:6.5pt;margin-bottom:2pt"><b>Bank:</b> '+esc(d.bank||'—')+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>Acc No:</b> '+esc(d.acc_no||'—')+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>Acc Name:</b> '+esc(d.acc_name||'—')+'</div><div style="font-size:6.5pt;margin-bottom:2pt"><b>Status:</b> '+esc(d.status||'Pending')+'</div><div style="font-size:6.5pt"><b>Paid:</b> '+(d.is_paid==1?'Yes':'No')+'</div></div></div>'+
  '</div>'+
  '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12pt;margin-top:14pt"><div style="text-align:center"><div style="height:30pt;border-bottom:1.5pt solid #4a554c;margin-bottom:3pt"></div><span style="font-size:5pt;font-weight:800;letter-spacing:.6pt;text-transform:uppercase;color:#5a554c">Client Signature</span><small style="font-size:4.5pt;color:#9aa79c;display:block;margin-top:1pt">Name &amp; Date</small></div><div style="text-align:center"><div style="height:30pt;border-bottom:1.5pt solid #4a554c;margin-bottom:3pt"></div><span style="font-size:5pt;font-weight:800;letter-spacing:.6pt;text-transform:uppercase;color:#5a554c">Dispatch Officer</span><small style="font-size:4.5pt;color:#9aa79c;display:block;margin-top:1pt">Name &amp; Date</small></div><div style="text-align:center"><div style="height:30pt;border-bottom:1.5pt solid #4a554c;margin-bottom:3pt"></div><span style="font-size:5pt;font-weight:800;letter-spacing:.6pt;text-transform:uppercase;color:#5a554c">Authorised By</span><small style="font-size:4.5pt;color:#9aa79c;display:block;margin-top:1pt">Name &amp; Date</small></div></div>'+
  '<div style="margin-top:10pt;padding-top:5pt;border-top:1pt solid #dfe5dd;display:flex;justify-content:space-between;font-size:5pt;color:#9aa79c"><span style="color:#c0392b;font-weight:800;letter-spacing:.5pt">CONFIDENTIAL — INTERNAL USE ONLY</span><span>'+esc(CO.name)+' &mdash; '+esc(d.order_no)+'</span><span>'+now+'</span></div>'+
  '</div>';
  var ps=$('printSheet');ps.innerHTML=h;
  toast('Preparing print...','success');
  setTimeout(function(){window.print();setTimeout(function(){ps.innerHTML='';},1000)},300);
}

document.querySelectorAll('.btn-print-ticket').forEach(function(b){b.addEventListener('click',function(){var tr=b.closest('tr');try{var d=JSON.parse(tr.dataset.bank);printTicket(d)}catch(e){toast('Error loading order','error')}})});

